from flask import Flask, request, jsonify
import json

app = Flask(__name__)

# In-memory storage for students
students = []

# In-memory storage for attendance records
attendance_records = []

def get_student_by_id(student_id):
    """Retrieve a student by their ID."""
    for student in students:
        if student['id'] == student_id:
            return student
    return None

def add_student(student_data):
    """Add a new student to the list."""
    if 'id' not in student_data:
        return {'error': 'Student ID is required'}

    # Check if student already exists
    for student in students:
        if student['id'] == student_data['id']:
            return {'error': 'Student already exists'}

    students.append(student_data)
    return {'message': 'Student added successfully', 'student': student_data}

def add_attendance(student_id, date, status):
    """
    Add an attendance record for a student.

    Args:
        student_id: The ID of the student
        date: The date of attendance (format: YYYY-MM-DD)
        status: Attendance status ('present', 'absent', 'late')

    Returns:
        JSON response with success/error message
    """
    # Validate date format - must be YYYY-MM-DD
    if not date or not isinstance(date, str):
        return {'error': 'Invalid date format. Expected YYYY-MM-DD'}

    # Check date format using regex
    import re
    if not re.match(r'^\d{4}-\d{2}-\d{2}$', date):
        return {'error': 'Invalid date format. Expected YYYY-MM-DD'}

    # Validate status
    valid_statuses = ['present', 'absent', 'late']
    if status not in valid_statuses:
        return {'error': f'Invalid status. Must be one of: {", ".join(valid_statuses)}'}

    # Check if student exists
    student = get_student_by_id(student_id)
    if not student:
        return {'error': f'Student with ID {student_id} not found'}, 404

    # Create attendance record
    record = {
        'student_id': student_id,
        'date': date,
        'status': status
    }

    attendance_records.append(record)
    return {'message': 'Attendance recorded successfully', 'record': record}

@app.route('/students', methods=['GET'])
def get_students():
    """Get all students."""
    return jsonify({'students': students})

@app.route('/students/<int:student_id>', methods=['GET'])
def get_student(student_id):
    """Get a specific student by ID."""
    student = get_student_by_id(student_id)
    if not student:
        return jsonify({'error': f'Student with ID {student_id} not found'}), 404
    return jsonify({'student': student})

@app.route('/students', methods=['POST'])
def add_student_endpoint():
    """Add a new student."""
    if request.content_type != 'application/json':
        return jsonify({'error': 'Content-Type must be application/json'}), 400

    data = request.get_json()
    if not data:
        return jsonify({'error': 'No JSON data provided'}), 400

    result = add_student(data)
    if 'error' in result:
        return jsonify(result), 400
    return jsonify(result), 201

@app.route('/attendance/<int:student_id>', methods=['POST'])
def add_attendance_endpoint(student_id):
    """
    Record attendance for a student.

    Validates:
    - Student exists
    - Date format is valid (YYYY-MM-DD)
    - Status is valid (present, absent, late)
    """
    data = request.get_json()
    if not data:
        return jsonify({'error': 'No JSON data provided'}), 400

    # Validate required fields
    required_fields = ['date', 'status']
    for field in required_fields:
        if field not in data:
            return jsonify({'error': f'Missing required field: {field}'}), 400

    result = add_attendance(student_id, data['date'], data['status'])
    if 'error' in result:
        return jsonify(result), 400
    return jsonify(result), 201

@app.route('/attendance/<int:student_id>', methods=['GET'])
def get_attendance(student_id):
    """Get all attendance records for a student."""
    student = get_student_by_id(student_id)
    if not student:
        return jsonify({'error': f'Student with ID {student_id} not found'}), 404

    student_records = [r for r in attendance_records if r['student_id'] == student_id]
    return jsonify({'student_id': student_id, 'records': student_records})

if __name__ == '__main__':
    app.run(debug=True, port=5000)
